const tree = { name: "A", children: [
  { name: "B", children: [{ name: "D", children: [] }] },
  { name: "C", children: [] },
] };

function visit(root, take) {
  const todo = [root];
  const seen = [];
  while (todo.length > 0) {
    const node = take(todo);
    seen.push(node.name);
    todo.push(...node.children);
  }
  return seen.join("");
}

console.log(visit(tree, (list) => list.shift()), visit(tree, (list) => list.pop()));

function collect(node, out = []) {
  out.push(node.name);
  for (const child of node.children) collect(child, out);
  return out;
}

const a = collect({ name: "Rice", children: [] });
const b = collect({ name: "Oil", children: [{ name: "Palm", children: [] }] });
console.log(a.length, b.length);

