function sumNested(list) {
  let total = 0;
  const stack = [list];
  while (stack.length > 0) {
    const current = stack.pop();
    for (const item of current) {
      if (Array.isArray(item)) stack.push(item);
      else total += item;
    }
  }
  return total;
}

let deep = [1];
for (let i = 0; i < 50000; i++) deep = [1, deep];
console.log(sumNested([1, [2, [3]], 4]));
try {
  console.log(sumNested(deep));
} catch (error) {
  console.log(error.name);
