function breadcrumbs(category, trail = []) {
  const path = [...trail, category.name];
  const result = [path.join(" > ")];
  for (const child of category.children) result.push(...breadcrumbs(child, path));
  return result;
}

const food = { name: "Food", children: [
  { name: "Grains", children: [{ name: "Rice", children: [] }] },
  { name: "Oils", children: [] },
] };
